        return str(len(a)) + "\n" + " ".join(map(str, a))
    tests = [fmt([6, 2, 9, 3, 3, 8]), fmt([5, 4, 3, 2, 1]), fmt([1, 2, 3, 4]), fmt([7]), fmt([2, 2, 2]),
             fmt([-3, -5, -1, -1, 0]), fmt([1, 3, 2, 4])]
    for n in (2, 3, 4, 6, 8, 10, 15, 20, 40):
        for hi in (3, 50):
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    N = 200000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt(list(range(N, 0, -1))))
    tests.append(fmt(list(range(1, N + 1))))
    tests.append(fmt([rng.randint(1, 5) for _ in range(N)]))
    return tests

